<?php
require_once __DIR__.'/vnpay_gateway.php';
function vnp_api_signature(array $data,array $order,string $secret): string {return hash_hmac('sha512',implode('|',array_map(fn($k)=>(string)($data[$k]??''),$order)),$secret);}
function vnp_query(array $u,string $payment): string {
 must(can($u,'GHI_NHAN_THU'),'Không có quyền đối soát.',403);$p=db_one("SELECT * FROM hoa_don WHERE ma_hoa_don=? AND nguon_tham_chieu='VNPAY_SANDBOX' AND loai_giao_dich='THU'",[$payment]);must($p&&$p['tao_phien_luc'],'Giao dịch không có thông tin phiên VNPay.');contract($p['so_hop_dong'],$u);$c=vnp_config();
 $data=['vnp_RequestId'=>uid('Q'),'vnp_Version'=>'2.1.0','vnp_Command'=>'querydr','vnp_TmnCode'=>$c['tmn_code'],'vnp_TxnRef'=>$p['ma_phien_tt'],'vnp_TransactionDate'=>date('YmdHis',strtotime($p['tao_phien_luc'])),'vnp_CreateDate'=>date('YmdHis'),'vnp_IpAddr'=>$_SERVER['REMOTE_ADDR']??'127.0.0.1','vnp_OrderInfo'=>'Doi soat '.$payment];
 $order=['vnp_RequestId','vnp_Version','vnp_Command','vnp_TmnCode','vnp_TxnRef','vnp_TransactionDate','vnp_CreateDate','vnp_IpAddr','vnp_OrderInfo'];$data['vnp_SecureHash']=vnp_api_signature($data,$order,$c['hash_secret']);$curl=curl_init('https://sandbox.vnpayment.vn/merchant_webapi/api/transaction');curl_setopt_array($curl,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($data),CURLOPT_HTTPHEADER=>['Content-Type: application/json'],CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_TIMEOUT=>20,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2]);$raw=curl_exec($curl);$code=curl_getinfo($curl,CURLINFO_RESPONSE_CODE);curl_close($curl);must($raw!==false&&$code===200,'Chưa nhận được phản hồi đối soát. Trạng thái giao dịch được giữ nguyên.');$r=json_decode($raw,true);must(is_array($r),'Phản hồi không hợp lệ.');
 $order=['vnp_ResponseId','vnp_Command','vnp_ResponseCode','vnp_Message','vnp_TmnCode','vnp_TxnRef','vnp_Amount','vnp_BankCode','vnp_PayDate','vnp_TransactionNo','vnp_TransactionType','vnp_TransactionStatus','vnp_OrderInfo','vnp_PromotionCode','vnp_PromotionAmount'];$hash=$r['vnp_SecureHash']??'';must(is_string($hash)&&hash_equals(vnp_api_signature($r,$order,$c['hash_secret']),strtolower($hash)),'Chữ ký phản hồi đối soát không hợp lệ.');must(($r['vnp_TmnCode']??'')===$c['tmn_code']&&($r['vnp_TxnRef']??'')===$p['ma_phien_tt']&&($r['vnp_Command']??'')==='querydr','Phản hồi sai merchant hoặc phiên.');
 if(($r['vnp_ResponseCode']??'')!=='00')return 'VNPay chưa xác nhận truy vấn: '.($r['vnp_ResponseCode']??'không rõ');
 must(ltrim((string)($r['vnp_Amount']??''),'0')===vnp_amount($p['so_tien_thu'])&&($r['vnp_TransactionType']??'')==='01','Số tiền hoặc loại giao dịch đối soát không khớp.');
 if(($r['vnp_TransactionStatus']??'')==='00'){$date=DateTimeImmutable::createFromFormat('!YmdHis',$r['vnp_PayDate']??'');must($date&&$date->format('YmdHis')===$r['vnp_PayDate'],'Ngày giao dịch không hợp lệ.');settle_payment($payment,vnd($p['so_tien_thu']),valid_text((string)$r['vnp_TransactionNo'],100),'VNPAY_SANDBOX',true,$date->format('Y-m-d H:i:s'));return 'Đã đối soát giao dịch thành công.';}
 return 'Kết quả đã xác minh, mã trạng thái VNPay: '.($r['vnp_TransactionStatus']??'chưa rõ').'. Chưa ghi thêm tiền.';
}
